-- Witness votes vs. account activity (Hive), run on HAFSQL (hafsql-sql.mahdiyari.info, db haf_block_log, public login hafsql_public)
-- Snapshot: head block 111,809,727 (2026-11-19 21:23:03 UTC)
-- Activity "any"   = latest of: content vote, post/comment, account update, witness vote, proxy change, proposal vote
-- Activity "social"= latest of: content vote, post/comment
-- Valid votes = last approve per (account, witness), cast after the account's last vote expiration (expired_account_notification)
--               and after its last proxy change; stake = own vests (balances), proxied stake resolved up to 2 levels.

-- API  condenser_api.get_witnesses_by_vote ["", 400]   (on-chain totals and signing keys; used for ranks and enabled/disabled)
-- API  condenser_api.get_dynamic_global_properties    (HIVE per VEST)

-- wa3  per-witness stake by activity bucket (run 2026-11-19T21:27Z, 400 rows, 15.9 s)
WITH exp AS (SELECT account, max(id) eid FROM hafsql.operation_expired_account_notification_table GROUP BY 1),
pxo AS (SELECT account, max(id) pid FROM hafsql.operation_account_witness_proxy_table GROUP BY 1),
lw AS (SELECT DISTINCT ON (account,witness) account,witness,approve,id FROM hafsql.operation_account_witness_vote_table ORDER BY account,witness,id DESC),
gov AS (SELECT account, max(id) gid FROM hafsql.operation_account_witness_vote_table GROUP BY 1),
pv AS (SELECT voter, max(id) vid FROM hafsql.operation_update_proposal_votes_table GROUP BY 1),
cur AS (SELECT lw.account, lw.witness FROM lw LEFT JOIN exp ON exp.account=lw.account LEFT JOIN pxo ON pxo.account=lw.account WHERE lw.approve AND lw.id>coalesce(exp.eid,0) AND lw.id>coalesce(pxo.pid,0)),
vt AS (SELECT DISTINCT account FROM cur),
a0 AS (SELECT name, proxy, last_vote_time, last_post, last_update FROM hafsql.accounts WHERE name IN (SELECT account FROM vt) OR coalesce(proxy,'')<>''),
own AS (SELECT a.name, CASE WHEN coalesce(a.proxy,'')='' THEN a.name ELSE coalesce(nullif(p.proxy,''),a.proxy) END ev, greatest(a.last_vote_time, a.last_post::timestamp) ls, a.last_update::timestamp lu FROM a0 a LEFT JOIN a0 p ON p.name=a.proxy),
u AS (SELECT o.name, o.ev, o.ls, greatest(o.ls, o.lu, timestamp '2026-11-19 21:23:03' - ((111809727 - (greatest(coalesce(g.gid,0),coalesce(x.pid,0),coalesce(y.vid,0))>>32))*interval '3 seconds')) la, b.vests FROM own o JOIN hafsql.balances b ON b.account_name=o.name LEFT JOIN gov g ON g.account=o.name LEFT JOIN pxo x ON x.account=o.name LEFT JOIN pv y ON y.voter=o.name WHERE o.ev IN (SELECT account FROM vt) AND b.vests>0) SELECT c.witness, count(*) voters, round(sum(u.vests)) vests, round(coalesce(sum(u.vests) FILTER (WHERE coalesce(u.la,'2000-01-01')<timestamp '2026-11-19 21:23:03'-interval '6 months'),0)) la6m, round(coalesce(sum(u.vests) FILTER (WHERE coalesce(u.la,'2000-01-01')<timestamp '2026-11-19 21:23:03'-interval '1 year'),0)) la1y, round(coalesce(sum(u.vests) FILTER (WHERE coalesce(u.la,'2000-01-01')<timestamp '2026-11-19 21:23:03'-interval '2 years'),0)) la2y, round(coalesce(sum(u.vests) FILTER (WHERE coalesce(u.la,'2000-01-01')<timestamp '2026-11-19 21:23:03'-interval '3 years'),0)) la3y, round(coalesce(sum(u.vests) FILTER (WHERE coalesce(u.la,'2000-01-01')<timestamp '2026-11-19 21:23:03'-interval '4 years'),0)) la4y, round(coalesce(sum(u.vests) FILTER (WHERE coalesce(u.la,'2000-01-01')<timestamp '2026-11-19 21:23:03'-interval '5 years'),0)) la5y, round(coalesce(sum(u.vests) FILTER (WHERE coalesce(u.ls,'2000-01-01')<timestamp '2026-11-19 21:23:03'-interval '6 months'),0)) ls6m, round(coalesce(sum(u.vests) FILTER (WHERE coalesce(u.ls,'2000-01-01')<timestamp '2026-11-19 21:23:03'-interval '1 year'),0)) ls1y, round(coalesce(sum(u.vests) FILTER (WHERE coalesce(u.ls,'2000-01-01')<timestamp '2026-11-19 21:23:03'-interval '2 years'),0)) ls2y, round(coalesce(sum(u.vests) FILTER (WHERE coalesce(u.ls,'2000-01-01')<timestamp '2026-11-19 21:23:03'-interval '3 years'),0)) ls3y, round(coalesce(sum(u.vests) FILTER (WHERE coalesce(u.ls,'2000-01-01')<timestamp '2026-11-19 21:23:03'-interval '4 years'),0)) ls4y, round(coalesce(sum(u.vests) FILTER (WHERE coalesce(u.ls,'2000-01-01')<timestamp '2026-11-19 21:23:03'-interval '5 years'),0)) ls5y FROM cur c JOIN u ON u.ev=c.account GROUP BY c.witness ORDER BY 3 DESC LIMIT 400;

-- wa6  global stake by activity bucket (run 2026-11-19T21:28:57Z, 1 row, 12.7 s)
WITH exp AS (SELECT account, max(id) eid FROM hafsql.operation_expired_account_notification_table GROUP BY 1),
pxo AS (SELECT account, max(id) pid FROM hafsql.operation_account_witness_proxy_table GROUP BY 1),
lw AS (SELECT DISTINCT ON (account,witness) account,witness,approve,id FROM hafsql.operation_account_witness_vote_table ORDER BY account,witness,id DESC),
gov AS (SELECT account, max(id) gid FROM hafsql.operation_account_witness_vote_table GROUP BY 1),
pv AS (SELECT voter, max(id) vid FROM hafsql.operation_update_proposal_votes_table GROUP BY 1),
cur AS (SELECT lw.account, lw.witness FROM lw LEFT JOIN exp ON exp.account=lw.account LEFT JOIN pxo ON pxo.account=lw.account WHERE lw.approve AND lw.id>coalesce(exp.eid,0) AND lw.id>coalesce(pxo.pid,0)),
vt AS (SELECT DISTINCT account FROM cur),
a0 AS (SELECT name, proxy, last_vote_time, last_post, last_update FROM hafsql.accounts WHERE name IN (SELECT account FROM vt) OR coalesce(proxy,'')<>''),
own AS (SELECT a.name, CASE WHEN coalesce(a.proxy,'')='' THEN a.name ELSE coalesce(nullif(p.proxy,''),a.proxy) END ev, greatest(a.last_vote_time, a.last_post::timestamp) ls, a.last_update::timestamp lu FROM a0 a LEFT JOIN a0 p ON p.name=a.proxy),
u AS (SELECT o.name, o.ev, o.ls, greatest(o.ls, o.lu, timestamp '2026-11-19 21:23:03' - ((111809727 - (greatest(coalesce(g.gid,0),coalesce(x.pid,0),coalesce(y.vid,0))>>32))*interval '3 seconds')) la, b.vests FROM own o JOIN hafsql.balances b ON b.account_name=o.name LEFT JOIN gov g ON g.account=o.name LEFT JOIN pxo x ON x.account=o.name LEFT JOIN pv y ON y.voter=o.name WHERE o.ev IN (SELECT account FROM vt) AND b.vests>0) SELECT count(*) owners, round(sum(vests)) vests, count(*) FILTER (WHERE name<>ev) via_proxy, count(*) FILTER (WHERE coalesce(la,'2000-01-01')<timestamp '2026-11-19 21:23:03'-interval '6 months') nla6m, round(coalesce(sum(vests) FILTER (WHERE coalesce(la,'2000-01-01')<timestamp '2026-11-19 21:23:03'-interval '6 months'),0)) vla6m, count(*) FILTER (WHERE coalesce(la,'2000-01-01')<timestamp '2026-11-19 21:23:03'-interval '1 year') nla1y, round(coalesce(sum(vests) FILTER (WHERE coalesce(la,'2000-01-01')<timestamp '2026-11-19 21:23:03'-interval '1 year'),0)) vla1y, count(*) FILTER (WHERE coalesce(la,'2000-01-01')<timestamp '2026-11-19 21:23:03'-interval '2 years') nla2y, round(coalesce(sum(vests) FILTER (WHERE coalesce(la,'2000-01-01')<timestamp '2026-11-19 21:23:03'-interval '2 years'),0)) vla2y, count(*) FILTER (WHERE coalesce(la,'2000-01-01')<timestamp '2026-11-19 21:23:03'-interval '5 years') nla5y, round(coalesce(sum(vests) FILTER (WHERE coalesce(la,'2000-01-01')<timestamp '2026-11-19 21:23:03'-interval '5 years'),0)) vla5y, count(*) FILTER (WHERE coalesce(ls,'2000-01-01')<timestamp '2026-11-19 21:23:03'-interval '6 months') nls6m, round(coalesce(sum(vests) FILTER (WHERE coalesce(ls,'2000-01-01')<timestamp '2026-11-19 21:23:03'-interval '6 months'),0)) vls6m, count(*) FILTER (WHERE coalesce(ls,'2000-01-01')<timestamp '2026-11-19 21:23:03'-interval '1 year'),0)) vls1y_placeholder FROM u;
